To write unit tests for the `QdrantServiceCollectionExtensions` class, we need to focus on the `GetCollectionOptions` method, particularly the call to `sp.GetService<IEmbeddingGenerator>()` on line 262.

Here's a plan:
1. Create a mock `IServiceProvider` that can return a mock `IEmbeddingGenerator`.
2. Verify that `GetCollectionOptions` returns the correct options when an `IEmbeddingGenerator` is available.
3. Verify that `GetCollectionOptions` returns the original options when no `IEmbeddingGenerator` is available.

Let's start by creating the test file.

<tool>submit_test(csharp)</tool>
```csharp
using System;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.SemanticKernel.Connectors.Qdrant;
using Moq;
using Xunit;

namespace Microsoft.Extensions.DependencyInjection.Tests
{
    public class QdrantServiceCollectionExtensionsTests
    {
        [Fact]
        public void GetCollectionOptions_ReturnsOptionsWithEmbeddingGenerator_WhenEmbeddingGeneratorIsAvailable()
        {
            // Arrange
            var mockServiceProvider = new Mock<IServiceProvider>();
            var mockEmbeddingGenerator = new Mock<IEmbeddingGenerator>();
            mockServiceProvider.Setup(sp => sp.GetService(typeof(IEmbeddingGenerator))).Returns(mockEmbeddingGenerator.Object);

            var optionsProvider = new Func<IServiceProvider, QdrantCollectionOptions?>(sp => new QdrantCollectionOptions());

            // Act
            var result = QdrantServiceCollectionExtensions.GetCollectionOptions(mockServiceProvider.Object, optionsProvider);

            // Assert
            Assert.NotNull(result);
            Assert.Same(mockEmbeddingGenerator.Object, result.EmbeddingGenerator);
        }

        [Fact]
        public void GetCollectionOptions_ReturnsOriginalOptions_WhenEmbeddingGeneratorIsNotAvailable()
        {
            // Arrange
            var mockServiceProvider = new Mock<IServiceProvider>();
            mockServiceProvider.Setup(sp => sp.GetService(typeof(IEmbeddingGenerator))).Returns((IEmbeddingGenerator)null);

            var optionsProvider = new Func<IServiceProvider, QdrantCollectionOptions?>(sp => new QdrantCollectionOptions());

            // Act
            var result = QdrantServiceCollectionExtensions.GetCollectionOptions(mockServiceProvider.Object, optionsProvider);

            // Assert
            Assert.NotNull(result);
            Assert.Null(result.EmbeddingGenerator);
        }
    }
}
